import{_ as t,o as s,c as n,ag as l}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"居家燃脂计划","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/fitness/home-fat-burning.md","filePath":"topics/fitness/home-fat-burning.md"}'),p={name:"topics/fitness/home-fat-burning.md"};function e(i,a,r,o,d,h){return s(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="居家燃脂计划" tabindex="-1">居家燃脂计划 <a class="header-anchor" href="#居家燃脂计划" aria-label="Permalink to &quot;居家燃脂计划&quot;">​</a></h1><blockquote><p>来源：健身知识整理，适用大基数人群（90kg+），2026-06-16</p></blockquote><hr><h2 id="一、计划概述" tabindex="-1">一、计划概述 <a class="header-anchor" href="#一、计划概述" aria-label="Permalink to &quot;一、计划概述&quot;">​</a></h2><h3 id="适合人群" tabindex="-1">适合人群 <a class="header-anchor" href="#适合人群" aria-label="Permalink to &quot;适合人群&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>体重</td><td>大基数（90kg以上）</td></tr><tr><td>场地</td><td>居家，无需器械</td></tr><tr><td>时间</td><td>每天20分钟</td></tr><tr><td>频率</td><td>每天均可，休息日可选</td></tr><tr><td>基础要求</td><td>膝盖无严重伤病</td></tr></tbody></table><blockquote><p>⚠️ 大基数人群不适合跑步、跳绳等高冲击运动，优先选择低冲击有氧+力量组合。</p></blockquote><hr><h2 id="二、运动处方-每天20分钟" tabindex="-1">二、运动处方（每天20分钟） <a class="header-anchor" href="#二、运动处方-每天20分钟" aria-label="Permalink to &quot;二、运动处方（每天20分钟）&quot;">​</a></h2><h3 id="热身-正式组-放松" tabindex="-1">热身 + 正式组 + 放松 <a class="header-anchor" href="#热身-正式组-放松" aria-label="Permalink to &quot;热身 + 正式组 + 放松&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总时长：约20分钟</span></span>
<span class="line"><span>热身：2-3分钟（动起来）</span></span>
<span class="line"><span>正式组：15分钟（3组，每组5分钟，组间休息2-3分钟）</span></span>
<span class="line"><span>放松：2分钟（拉伸）</span></span></code></pre></div><hr><h2 id="三、每个动作详解" tabindex="-1">三、每个动作详解 <a class="header-anchor" href="#三、每个动作详解" aria-label="Permalink to &quot;三、每个动作详解&quot;">​</a></h2><h3 id="动作1-胯下击掌-⭐-热身激活" tabindex="-1">动作1：胯下击掌 ⭐ 热身激活 <a class="header-anchor" href="#动作1-胯下击掌-⭐-热身激活" aria-label="Permalink to &quot;动作1：胯下击掌 ⭐ 热身激活&quot;">​</a></h3><p><strong>目标</strong>：全身热身，激活心肺</p><p><strong>动作要领</strong>：</p><ol><li>站立，双脚与肩同宽</li><li>双手举起，在头顶上方击掌</li><li>同时抬起左腿，让膝盖尽量靠近胸口</li><li>双手从胯下穿过击掌（或者拍腿也可以）</li><li>换右腿，重复</li></ol><p><strong>次数</strong>：左右各30次 = 60次（新手可从30次起步）</p><p><strong>呼吸</strong>：抬起时呼气，放下时吸气</p><p><strong>组间休息</strong>：30秒</p><p><strong>感觉</strong>：轻微出汗，心率上升</p><p><strong>注意</strong>：</p><ul><li>膝盖有伤者减小幅度</li><li>不用跳，原地做即可</li></ul><hr><h3 id="动作2-对侧提膝-左右各60次" tabindex="-1">动作2：对侧提膝（左右各60次） <a class="header-anchor" href="#动作2-对侧提膝-左右各60次" aria-label="Permalink to &quot;动作2：对侧提膝（左右各60次）&quot;">​</a></h3><p><strong>目标</strong>：侧腰减脂，核心稳定</p><p><strong>动作要领</strong>：</p><ol><li>站立，双手自然下垂</li><li>抬起右膝，同时左手肘去碰右膝</li><li>右膝尽量抬高，肘膝在体前相遇</li><li>缓慢放下，换左膝，右手肘碰左膝</li><li>交替进行</li></ol><p><strong>次数</strong>：左右各30次 = 60次</p><p><strong>速度</strong>：2秒一提膝，不要太快</p><p><strong>组间休息</strong>：30-60秒</p><p><strong>注意</strong>：</p><ul><li>不要用惯性甩腿</li><li>核心收紧，背挺直</li><li>膝盖有伤减小幅度</li></ul><hr><h3 id="动作3-提膝下压-左右各60次" tabindex="-1">动作3：提膝下压（左右各60次） <a class="header-anchor" href="#动作3-提膝下压-左右各60次" aria-label="Permalink to &quot;动作3：提膝下压（左右各60次）&quot;">​</a></h3><p><strong>目标</strong>：下腹部减脂，马甲线</p><p><strong>动作要领</strong>：</p><ol><li>站立，双脚与肩同宽</li><li>抬起右膝，向前伸直踢出（腿伸直）</li><li>同时双手下压，拍打膝盖</li><li>收回右膝，换左膝，双手拍左膝</li><li>交替进行</li></ol><p><strong>次数</strong>：左右各30次 = 60次</p><p><strong>速度</strong>：中速，保持控制</p><p><strong>组间休息</strong>：30-60秒</p><p><strong>下腹感觉</strong>：酸胀感=做对了</p><p><strong>注意</strong>：</p><ul><li>踢腿时脚尖勾起（保护膝盖）</li><li>不要用惯性甩，要控制</li></ul><hr><h3 id="动作4-深蹲-30次" tabindex="-1">动作4：深蹲（30次） <a class="header-anchor" href="#动作4-深蹲-30次" aria-label="Permalink to &quot;动作4：深蹲（30次）&quot;">​</a></h3><p><strong>目标</strong>：下肢燃脂，臀腿力量</p><p><strong>动作要领</strong>：</p><ol><li>站立，双脚略宽于肩，脚尖略微外展（30度）</li><li>臀部向后坐，下蹲</li><li>膝盖沿脚尖方向（不内扣）</li><li>下蹲至大腿与地面平行或略低</li><li>臀大肌发力，起身</li></ol><p><strong>次数</strong>：30次 × 3组</p><p><strong>组间休息</strong>：60-90秒</p><p><strong>速度</strong>：</p><ul><li>下蹲：2秒（慢蹲）</li><li>起身：1秒（爆发）</li></ul><p><strong>正确信号</strong>：</p><ul><li>膝盖不痛</li><li>大腿前侧（股四）和臀部酸胀</li><li>膝盖不超过脚尖太多</li></ul><p><strong>常见错误</strong>：</p><ul><li>❌ 膝盖内扣（伤膝盖）→ 纠正：膝盖沿脚尖方向</li><li>❌ 腰弯背弓（伤腰椎）→ 纠正：挺胸，背打直</li><li>❌ 蹲太浅 → 纠正：至少大腿平行</li></ul><hr><h2 id="四、完整流程-每天照做" tabindex="-1">四、完整流程（每天照做） <a class="header-anchor" href="#四、完整流程-每天照做" aria-label="Permalink to &quot;四、完整流程（每天照做）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【热身】2-3分钟</span></span>
<span class="line"><span>  原地高抬腿 30秒</span></span>
<span class="line"><span>  胯下击掌 30次</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>【正式组1】5分钟</span></span>
<span class="line"><span>  对侧提膝 30次（左右各15次）</span></span>
<span class="line"><span>  休息 30秒</span></span>
<span class="line"><span>  对侧提膝 30次</span></span>
<span class="line"><span>  休息 30秒</span></span>
<span class="line"><span>  提膝下压 30次（左右各15次）</span></span>
<span class="line"><span>  休息 30秒</span></span>
<span class="line"><span>  提膝下压 30次</span></span>
<span class="line"><span>  休息 30秒</span></span>
<span class="line"><span>  深蹲 30次</span></span>
<span class="line"><span>  休息 60秒</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【正式组2】5分钟</span></span>
<span class="line"><span>  （同组1，重复一遍）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【正式组3】5分钟</span></span>
<span class="line"><span>  （同组1，重复一遍）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【放松】2分钟</span></span>
<span class="line"><span>  拉伸大腿前侧（左右各30秒）</span></span>
<span class="line"><span>  拉伸小腿（左右各30秒）</span></span></code></pre></div><p><strong>总用时</strong>：约 20-22 分钟</p><hr><h2 id="五、配套建议" tabindex="-1">五、配套建议 <a class="header-anchor" href="#五、配套建议" aria-label="Permalink to &quot;五、配套建议&quot;">​</a></h2><h3 id="饮食配合-比运动更重要" tabindex="-1">饮食配合（比运动更重要） <a class="header-anchor" href="#饮食配合-比运动更重要" aria-label="Permalink to &quot;饮食配合（比运动更重要）&quot;">​</a></h3><blockquote><p>减脂七分吃，三分练。运动是辅助，饮食是核心。</p></blockquote><p><strong>大基数减脂饮食原则</strong>：</p><table tabindex="0"><thead><tr><th>原则</th><th>说明</th><th>操作</th></tr></thead><tbody><tr><td>戒糖</td><td>不喝奶茶/可乐/果汁</td><td>改喝无糖茶/黑咖啡</td></tr><tr><td>减少精制碳水</td><td>少吃白米饭/面条</td><td>替换成杂粮饭/荞麦面/红薯</td></tr><tr><td>增加蛋白质</td><td>每餐有肉/蛋/豆腐</td><td>目标：每天1.2g/kg体重蛋白质</td></tr><tr><td>多吃蔬菜</td><td>每餐先吃菜</td><td>增强饱腹感</td></tr><tr><td>不吃宵夜</td><td>晚上8点后不进食</td><td>坚持就是胜利</td></tr><tr><td>多喝水</td><td>每天2-2.5L</td><td>促进代谢</td></tr></tbody></table><p><strong>示例一日三餐</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>早餐：鸡蛋2个 + 无糖豆浆 + 半个红薯</span></span>
<span class="line"><span>午餐：鸡胸肉/鱼 + 大量蔬菜 + 半碗杂粮饭</span></span>
<span class="line"><span>晚餐：豆腐/鸡蛋 + 大量蔬菜 + 不吃主食</span></span></code></pre></div><hr><h3 id="心率区间-靶心率" tabindex="-1">心率区间（靶心率） <a class="header-anchor" href="#心率区间-靶心率" aria-label="Permalink to &quot;心率区间（靶心率）&quot;">​</a></h3><p><strong>目标燃脂心率</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最大心率 = 220 - 年龄</span></span>
<span class="line"><span></span></span>
<span class="line"><span>减脂区间 = 最大心率 × 60% ~ 75%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例如：30岁，最大心率190</span></span>
<span class="line"><span>→ 燃脂心率：114 ~ 143 次/分钟</span></span></code></pre></div><p><strong>自测</strong>：能说话但不能唱歌 = 燃脂心率</p><hr><h3 id="休息安排" tabindex="-1">休息安排 <a class="header-anchor" href="#休息安排" aria-label="Permalink to &quot;休息安排&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>说明</th></tr></thead><tbody><tr><td>每天做</td><td>适合体能较好、无伤病者</td></tr><tr><td>做5休2</td><td>适合大多数人</td></tr><tr><td>做3休1</td><td>适合刚开始、体能较差者</td></tr></tbody></table><p><strong>注意</strong>：感觉膝盖不适，立刻停止，不要硬撑。</p><hr><h2 id="六、进阶路线" tabindex="-1">六、进阶路线 <a class="header-anchor" href="#六、进阶路线" aria-label="Permalink to &quot;六、进阶路线&quot;">​</a></h2><h3 id="初级-→-中级-→-高级" tabindex="-1">初级 → 中级 → 高级 <a class="header-anchor" href="#初级-→-中级-→-高级" aria-label="Permalink to &quot;初级 → 中级 → 高级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>变化</th></tr></thead><tbody><tr><td>初级（第1-4周）</td><td>每天20分钟</td><td>动作从30次起步，组间休息90秒</td></tr><tr><td>中级（第5-12周）</td><td>每天25分钟</td><td>次数增加到40次，组间休息60秒</td></tr><tr><td>高级（12周后）</td><td>每天30分钟</td><td>加入开合跳/波比跳（低冲击版）</td></tr></tbody></table><p><strong>大基数进阶警告</strong>：</p><ul><li>体重降到80kg以下再考虑跑步</li><li>体重降到75kg以下再考虑跳绳</li><li>任何时候膝盖不适立即停止</li></ul><hr><h2 id="七、效果预期" tabindex="-1">七、效果预期 <a class="header-anchor" href="#七、效果预期" aria-label="Permalink to &quot;七、效果预期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>预期效果</th></tr></thead><tbody><tr><td>第1周</td><td>腰围减少0.5-1cm，精神变好</td></tr><tr><td>第2-4周</td><td>裤子变松，体重降2-4斤</td></tr><tr><td>第1-3个月</td><td>体重降10-20斤（配合饮食）</td></tr><tr><td>3-6个月</td><td>明显变瘦，体能大幅提升</td></tr></tbody></table><blockquote><p><strong>关键</strong>：前3周最难熬，坚持过去就是习惯。运动最难的从来不是动作，是开始。</p></blockquote>`,88)])])}const b=t(p,[["render",e]]);export{g as __pageData,b as default};
